sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.script:
(function() {

    // ==========================================
    // COMPLAINT TABLE
    // ==========================================

    var COMPLAINT_TABLE = 'x_snc_environmen_0_complaint';


    // ==========================================
    // 1. TOTAL COMPLAINTS
    // ==========================================

    var total = new GlideAggregate(COMPLAINT_TABLE);
    total.addAggregate('COUNT');
    total.query();

    data.totalComplaints = 0;

    if (total.next()) {
        data.totalComplaints =
            parseInt(total.getAggregate('COUNT'), 10) || 0;
    }


    // ==========================================
    // 2. HIGH RISK COMPLAINTS
    // ==========================================

    var highRisk = new GlideAggregate(COMPLAINT_TABLE);

    highRisk.addQuery('risk_level', 'High');
    highRisk.addAggregate('COUNT');
    highRisk.query();

    data.highRisk = 0;

    if (highRisk.next()) {
        data.highRisk =
            parseInt(highRisk.getAggregate('COUNT'), 10) || 0;
    }


    // ==========================================
    // 3. COMPLIANT COMPLAINTS
    // ==========================================

    var resolved = new GlideAggregate(COMPLAINT_TABLE);

    resolved.addQuery('compliance_status', 'compliant');
    resolved.addAggregate('COUNT');
    resolved.query();

    data.resolvedCases = 0;

    if (resolved.next()) {
        data.resolvedCases =
            parseInt(resolved.getAggregate('COUNT'), 10) || 0;
    }


    // ==========================================
    // 3A. COMPLETION PERCENTAGE
    // ==========================================

    data.completionPercentage = 0;

    if (data.totalComplaints > 0) {

        data.completionPercentage =
            Math.round(
                (data.resolvedCases / data.totalComplaints) * 100
            );
    }


    // ==========================================
    // INSPECTION TABLE
    // ==========================================

    var INSPECTION_TABLE =
        'x_snc_environmen_0_inspection';


    // ==========================================
    // 4. INSPECTION STATUS
    // ==========================================

    data.activeInspections = 0;
    data.completedInspections = 0;
    data.pendingInspections = 0;


    var inspection =
        new GlideRecord(INSPECTION_TABLE);

    inspection.query();


    while (inspection.next()) {

        var status =
            inspection.getValue('inspection_status');


        // ======================================
        // ACTIVE
        // Assigned + In Progress
        // ======================================

        if (
            status == 'assigned' ||
            status == 'in_progress'
        ) {

            data.activeInspections++;

        }


        // ======================================
        // COMPLETED
        // Completed + Closed
        // ======================================

        else if (
            status == 'completed' ||
            status == 'closed'
        ) {

            data.completedInspections++;

        }


        // ======================================
        // PENDING
        // Re-Inspection Required
        // ======================================

        else if (
            status == 're_inspection_required'
        ) {

            data.pendingInspections++;

        }

    }


    // ==========================================
    // 5. TOTAL INSPECTIONS
    // ==========================================

    data.totalWorkOrders =
        data.activeInspections +
        data.completedInspections +
        data.pendingInspections;


})();
